// Defining props for a product object
defineProps({
  title: String,
  price: Number,
  inStock: Boolean
})

// Example prop configuration with required and defaults
defineProps({
  username: {
    type: String,
    required: true
  },
  score: {
    type: Number,
    default: 0
  },
  isOnline: {
    type: Boolean,
    default: false
  }
})

// Example: creating reactive state
import { ref } from 'vue';
const count = ref(0);

// Example: a method that updates a ref
function updateCount() {
  count.value = count.value + 1;
}

// Example computed property
import { computed } from 'vue';

const fullName = computed(() => `${firstName} ${lastName}`);
